def _record(locus):
    page = int(locus.split("_")[-1].split(".")[0])
    evidence = (
        f"Manual comparison with Headlam–Knox 1922, PDF page {page}, printed "
        f"page {page - 70}, {SCOPES[locus]}; PDF SHA256 {SOURCE_SHA256}. "
        f"Original same-scan color page SHA256 {SOURCE_IMAGES[page]}, archive "
        f"SHA256 {SOURCE_IMAGE_ARCHIVE_SHA256}; retained in "
        "data/corpus_changes/herodas-reading-sources/manifest.json. Original "
        "color pixels and focused 8–12× PDF renders were inspected; this is "
        "one photographic source, not an independent witness."
    )
    if locus in CROSS_REVIEW:
        evidence += " Independent second inspection of the same scan: " + CROSS_REVIEW[locus]
    text = CORRECTED[locus]
    uncertainties = []
    for marker, alternatives, reason in UNCERTAIN.get(locus, []):
        if text.count(marker) != 1:
            raise ValueError(f"Missing or repeated Herodas uncertainty preimage: {locus}, {marker}")
        start = text.index(marker)
        uncertainties.append({"start": start, "end": start + len(marker),
            "text": marker, "alternatives": alternatives,
            "evidence": evidence + " " + reason})
    return {"original_text": ORIGINAL[locus], "corrected_text": text,
        "source_sha256": SOURCE_SHA256, "scan_page": page,
        "evidence": evidence, "reviewed_at": REVIEWED_AT,
        "uncertainties": uncertainties}


if set(ORIGINAL) != set(CORRECTED) or set(ORIGINAL) != set(SCOPES):
    raise ValueError("Herodas excerpt review does not account for every assigned passage")
READINGS = {locus: _record(locus) for locus in ORIGINAL}

